$ ../../zig/build/stage3/bin/zig c++ test.cpp $(xcrun --show-sdk-path)/usr/lib/libc++.tbd -nostdlib++ -nostdinc++ -I $(xcrun --show-sdk-path)/usr/include -I $(xcrun --show-sdk-path)/usr/include/c++/v1

